public class Main {static class Fast {byte[] b=new byte[65536];int p,l;int read()throws Exception{if(p==l){l=System.in.read(b);p=0;if(l<0)return -1;}return b[p++];}String next()throws Exception{StringBuilder s=new StringBuilder();int c;do{c=read();}while(c<=32&&c!=-1);while(c>32){s.append((char)c);c=read();}return s.toString();}int number()throws Exception{return Integer.parseInt(next());}}
 static void fixed(StringBuilder out,double value){long x=Math.round(value*100000000.0);if(x<0){out.append('-');x=-x;}out.append(x/100000000).append('.');long f=x%100000000;for(long place=10000000;place>0;place/=10)out.append((char)('0'+(f/place)%10));}
 public static void main(String[] args)throws Exception{Fast in=new Fast();int t=in.number();StringBuilder out=new StringBuilder();int[] dx={1,0,-1,-1,0,1},dy={0,1,1,0,-1,-1};while(t-->0){int n=in.number(),q=in.number();String s=in.next();int[] x=new int[n+1],y=new int[n+1],rot=new int[n+1];for(int i=1;i<=n;i++){rot[i]=(rot[i-1]+s.charAt(i-1)-'0')%6;x[i]=x[i-1]+dx[rot[i]];y[i]=y[i-1]+dy[rot[i]];}while(q-->0){int l=in.number(),r=in.number(),u=x[r]-x[l-1],v=y[r]-y[l-1];for(int k=0;k<rot[l-1];k++){int next=u+v;v=-u;u=next;}fixed(out,u+v*0.5);out.append(' ');fixed(out,v*(Math.sqrt(3)/2));out.append('\n');}}System.out.print(out);}}
